/**
 * Seeds: 6 system roles, Permission rows generated by walking shared-menu's msd-menu.json,
 * every Permission auto-linked to the `super_admin` role (the ONLY place the isSuperAdmin
 * flag drives any logic — application/route code must never check it directly), and a
 * couple of DashboardWidget rows assigned differently per role.
 *
 * Run with: npx prisma db seed --schema=apps/msd-api/prisma/schema.prisma
 * (wired via the root package.json "prisma.seed" script — see package.json).
 */
import * as path from 'path';
import * as dotenv from 'dotenv';

// seed.ts is run standalone (tsx), not through main.ts's bootstrap, so it needs its own
// env load. Prisma's CLI only auto-loads a file literally named `.env`; this repo's
// convention is `.env.local`, hence the explicit dotenv.config() here.
dotenv.config({ path: path.join(__dirname, '../.env.local') });

import { PrismaClient, Prisma } from '../src/generated/prisma-client';
import type { PermissionAction, MenuNode } from '@skylabs-monorepo/shared-types';
import { permissionKeyFor } from '@skylabs-monorepo/shared-permissions';
import { ensureUniqueSlug, slugify } from '../src/lib/slug';
import { getMenuForApp } from '@skylabs-monorepo/shared-menu';
import { normalizeIdentifier } from '../src/lib/normalizeIdentifier';
import { CATEGORY_TAXONOMY } from './category-taxonomy';

const prisma = new PrismaClient();

interface RoleSeed {
  key: string;
  name: string;
  description: string;
  isSystem: boolean;
  isSuperAdmin: boolean;
}

const ROLES: RoleSeed[] = [
  { key: 'super_admin', name: 'Super Admin', description: 'Full unrestricted access to every module.', isSystem: true, isSuperAdmin: true },
  { key: 'admin', name: 'Admin', description: 'MSD staff — full moderation and CRUD.', isSystem: true, isSuperAdmin: false },
  { key: 'customer', name: 'Customer', description: 'Consumer-facing base role.', isSystem: true, isSuperAdmin: false },
  { key: 'vendor', name: 'Vendor', description: 'Company/vendor owner or manager.', isSystem: true, isSuperAdmin: false },
  { key: 'marketing', name: 'Marketing', description: 'Content, promotions, categories.', isSystem: true, isSuperAdmin: false },
  { key: 'sales', name: 'Sales', description: 'Vendor accounts and reporting.', isSystem: true, isSuperAdmin: false },
];

/** Per-menuKey action subset. Every node gets 'view' at minimum (added below); this map adds the rest. */
const EXTRA_ACTIONS_BY_MENU_KEY: Record<string, PermissionAction[]> = {
  customers: ['create', 'edit', 'delete', 'export'],
  // 'custom' gates the vendor's own `/vendors/me*` self-service surface — granted only to the
  // `vendor` role (never `view`, which would leak the admin "list every vendor" endpoint).
  vendors: ['create', 'edit', 'delete', 'export', 'approve', 'reject', 'status_change', 'custom'],
  orders: ['create', 'edit', 'delete', 'export', 'status_change'],
  products: ['create', 'edit', 'delete', 'export'],
  services: ['create', 'edit', 'delete', 'export'],
  inventory: ['create', 'edit', 'delete', 'export'],
  reports: ['export'],
  // Categories and Sub Categories are the same underlying Category table (parentId null vs
  // set) — the backend gates all of it on 'masters.categories' (see categories.routes.ts);
  // 'masters.sub-categories' only needs its own Permission rows so the *second* sidebar item
  // (a distinct menu node) has something to grant :view on for visibility.
  'masters.categories': ['create', 'edit', 'delete'],
  'masters.sub-categories': ['create', 'edit', 'delete'],
  'masters.tags': ['create', 'edit', 'delete'],
  'rbac.roles': ['create', 'edit', 'delete', 'status_change'],
  'rbac.users': ['create', 'edit', 'delete', 'assign', 'status_change', 'custom'],
  'rbac.audit-logs': [],
  settings: ['edit'],
};

function flattenMenu(nodes: readonly MenuNode[]): MenuNode[] {
  const out: MenuNode[] = [];
  for (const node of nodes) {
    out.push(node);
    if (node.children) out.push(...flattenMenu(node.children));
  }
  return out;
}

function actionsForMenuKey(menuKey: string): PermissionAction[] {
  const extra = EXTRA_ACTIONS_BY_MENU_KEY[menuKey] ?? [];
  return ['view' as PermissionAction, ...extra.filter((a) => a !== 'view')];
}

async function seedRoles() {
  const roles = new Map<string, { id: string; isSuperAdmin: boolean }>();
  for (const roleSeed of ROLES) {
    const role = await prisma.role.upsert({
      where: { key: roleSeed.key },
      update: {
        name: roleSeed.name,
        description: roleSeed.description,
        isSystem: roleSeed.isSystem,
        isSuperAdmin: roleSeed.isSuperAdmin,
      },
      create: roleSeed,
    });
    roles.set(role.key, { id: role.id, isSuperAdmin: role.isSuperAdmin });
  }
  return roles;
}

async function seedPermissions(): Promise<Map<string, string>> {
  const menu = flattenMenu(getMenuForApp('msd'));
  const permissionIdByKey = new Map<string, string>();

  for (const node of menu) {
    for (const action of actionsForMenuKey(node.permissionKey)) {
      const key = permissionKeyFor(node.permissionKey, action);
      const permission = await prisma.permission.upsert({
        where: { key },
        update: { label: `${node.title} — ${action}` },
        create: { menuKey: node.permissionKey, action, key, label: `${node.title} — ${action}` },
      });
      permissionIdByKey.set(key, permission.id);
    }
  }

  return permissionIdByKey;
}

/**
 * SuperAdmin gets every Permission row EXCEPT `vendor-portal:*`. That menu key only makes sense
 * for an actual Vendor owner — it drives the self-service "My Business" surface (vendor-profile/
 * vendor-branches-deals/vendor-deals/vendor-customers/vendor-therapists), all scoped to the
 * caller's OWN Vendor row via `ownerUserId` — which a SuperAdmin never has. Granting it anyway
 * used to put the vendor-portal "Branches"/"Customers" sidebar nodes alongside the admin-wide
 * "Branches"/"Customers" nodes for every SuperAdmin — same-looking titles, and the vendor-portal
 * ones 404/render empty since the SuperAdmin owns no Vendor. (See the matching exclusion in
 * `permission-resolver.service.ts`'s `resolveGrantedPermissionKeys` — THAT is what actually
 * governs a SuperAdmin's live-resolved permissions/bootstrap menu, since it recomputes from the
 * live menu tree for any `isSuperAdmin`-flagged role rather than reading RolePermission at all;
 * this seed-time grant only matters for what the Role Permission Matrix editor *displays* as
 * checked for the Super Admin role.)
 */
async function grantAllPermissionsToSuperAdmins(
  roles: Map<string, { id: string; isSuperAdmin: boolean }>,
  permissionIdByKey: Map<string, string>,
) {
  const allPermissionIds = [...permissionIdByKey.entries()]
    .filter(([key]) => !key.startsWith('vendor-portal:'))
    .map(([, id]) => id);
  for (const role of roles.values()) {
    if (!role.isSuperAdmin) continue;
    await prisma.rolePermission.deleteMany({ where: { roleId: role.id } });
    await prisma.rolePermission.createMany({
      data: allPermissionIds.map((permissionId) => ({ roleId: role.id, permissionId })),
      skipDuplicates: true,
    });
  }
}

/** A reasonable starter grant for the non-super-admin staff roles, so the app isn't empty on first login. */
async function grantStarterPermissions(
  roles: Map<string, { id: string; isSuperAdmin: boolean }>,
  permissionIdByKey: Map<string, string>,
) {
  const grant = async (roleKey: string, keys: string[]) => {
    const role = roles.get(roleKey);
    if (!role) return;
    const ids = keys.map((k) => permissionIdByKey.get(k)).filter((v): v is string => Boolean(v));
    await prisma.rolePermission.createMany({
      data: ids.map((permissionId) => ({ roleId: role.id, permissionId })),
      skipDuplicates: true,
    });
  };

  await grant('admin', [
    'dashboard:view',
    'customers:view', 'customers:create', 'customers:edit', 'customers:delete',
    'vendors:view', 'vendors:create', 'vendors:edit', 'vendors:delete',
    'vendors:approve', 'vendors:reject', 'vendors:status_change',
    'orders:view', 'orders:edit', 'orders:status_change',
    'products:view', 'products:create', 'products:edit', 'products:delete',
    'services:view', 'services:create', 'services:edit', 'services:delete',
    'inventory:view', 'inventory:create', 'inventory:edit', 'inventory:delete',
    'reports:view',
    'masters:view', 'masters.categories:view', 'masters.categories:create', 'masters.categories:edit', 'masters.categories:delete',
    'masters.sub-categories:view', 'masters.sub-categories:create', 'masters.sub-categories:edit', 'masters.sub-categories:delete',
    'masters.tags:view', 'masters.tags:create', 'masters.tags:edit', 'masters.tags:delete',
    'settings:view', 'settings:edit',
  ]);

  await grant('marketing', [
    'dashboard:view',
    'masters:view', 'masters.categories:view', 'masters.categories:create', 'masters.categories:edit',
    'masters.sub-categories:view', 'masters.sub-categories:create', 'masters.sub-categories:edit',
    'masters.tags:view', 'masters.tags:create', 'masters.tags:edit', 'masters.tags:delete',
    'reports:view',
  ]);

  await grant('sales', [
    'dashboard:view',
    'vendors:view', 'vendors:edit',
    'orders:view', 'orders:export',
    'reports:view', 'reports:export',
  ]);

  await grant('customer', ['dashboard:view']);
  // Deliberately NOT 'vendors:view' — that would also unlock the admin "list every vendor"
  // endpoint (requirePermission only checks the boolean grant, not who's asking). 'custom'
  // gates only the ownership-scoped `/vendors/me*` self-service surface. 'vendor-portal:view'
  // is a separate, narrower menu key that only surfaces the "My Business" sidebar item —
  // never granted to admin/customer/etc., so it can't leak the admin Vendors/Branches/Deals nav.
  // 'orders:status_change' lets a vendor confirm/complete/cancel its OWN orders —
  // order.service.ts still enforces vendor-ownership scoping and a narrower transition set
  // server-side; the permission alone only gates whether the action UI/route is reachable at all.
  await grant('vendor', ['dashboard:view', 'orders:view', 'orders:status_change', 'products:view', 'services:view', 'vendors:custom', 'vendor-portal:view']);
}

async function seedDashboardWidgets(roles: Map<string, { id: string; isSuperAdmin: boolean }>) {
  const widgets = [
    { key: 'customers-count', title: 'Total Customers', module: 'customers', description: 'Count of active customers.' },
    // Was "Recent Orders" / a hardcoded fake order list — GET /dashboard/stats only exposes a
    // total order count (no per-order listing endpoint backs this widget), so the widget and its
    // catalog title/description were updated together to match what it actually renders now.
    { key: 'orders-recent', title: 'Total Orders', module: 'orders', description: 'Total number of orders across all vendors.' },
    { key: 'revenue-summary', title: 'Revenue Summary', module: 'reports', description: 'Revenue rollup for the current period.' },
    { key: 'vendor-profile', title: 'My Business', module: 'vendors', description: "Entry point to the vendor's own business profile, branches, and deals." },
    // Added alongside the above for the real GET /dashboard/stats-backed marketplace overview.
    { key: 'vendors-count', title: 'Total Vendors', module: 'vendors', description: 'Count of vendors on the marketplace.' },
    { key: 'branches-count', title: 'Total Branches', module: 'vendors', description: 'Count of vendor branches/outlets.' },
    { key: 'categories-count', title: 'Total Categories', module: 'masters', description: 'Count of top-level categories.' },
    { key: 'subcategories-count', title: 'Total Sub Categories', module: 'masters', description: 'Count of sub-categories.' },
    { key: 'services-count', title: 'Total Services', module: 'services', description: 'Count of bookable services.' },
    { key: 'products-count', title: 'Total Products', module: 'products', description: 'Count of purchasable products.' },
    { key: 'deals-count', title: 'Total Deals', module: 'vendors', description: 'Count of deals/packages across all vendors.' },
  ];

  const widgetIdByKey = new Map<string, string>();
  for (const widget of widgets) {
    const row = await prisma.dashboardWidget.upsert({
      where: { key: widget.key },
      update: widget,
      create: widget,
    });
    widgetIdByKey.set(widget.key, row.id);
  }

  const assign = async (roleKey: string, keysInOrder: string[]) => {
    const role = roles.get(roleKey);
    if (!role) return;
    await prisma.roleDashboardWidget.deleteMany({ where: { roleId: role.id } });
    await prisma.roleDashboardWidget.createMany({
      data: keysInOrder.map((key, order) => ({
        roleId: role.id,
        widgetId: widgetIdByKey.get(key)!,
        order,
      })),
    });
  };

  // SuperAdmin sees every widget, same principle as grantAllPermissionsToSuperAdmins above.
  for (const [key, role] of roles.entries()) {
    if (role.isSuperAdmin) await assign(key, widgets.map((w) => w.key));
  }

  await assign('admin', [
    'customers-count',
    'orders-recent',
    'revenue-summary',
    'vendors-count',
    'branches-count',
    'categories-count',
    'subcategories-count',
    'services-count',
    'products-count',
    'deals-count',
  ]);
  await assign('sales', ['revenue-summary', 'orders-recent']);
  await assign('marketing', ['customers-count']);
  // Vendor's own entry point to /account/vendors — the sidebar item itself is admin-only
  // (see the `vendors:custom` note above), so this widget is how a vendor user reaches it.
  await assign('vendor', ['vendor-profile']);
}

/**
 * Pre-creates the SuperAdmin user (with the super_admin role already attached) so their
 * *first* OTP login doesn't fall through `loginWithIdentifier`'s "no roles yet -> default to
 * customer" path (see auth.service.ts). Identifier comes from SUPERADMIN_PHONE/
 * SUPERADMIN_EMAIL in .env.local — skipped (not guessed) if neither is set.
 */
async function seedSuperAdminUser(roles: Map<string, { id: string; isSuperAdmin: boolean }>) {
  const rawPhone = process.env.SUPERADMIN_PHONE || undefined;
  const email = process.env.SUPERADMIN_EMAIL || undefined;
  if (!rawPhone && !email) {
    console.log('SUPERADMIN_PHONE/SUPERADMIN_EMAIL not set — skipping SuperAdmin user seed.');
    return;
  }
  // Normalized to the same canonical form every real login identifier is now normalized to
  // at the auth boundary (see src/lib/normalizeIdentifier.ts) — without this, a SuperAdmin
  // seeded from the env var's raw bare-digit phone would never match a real login again.
  const phone = rawPhone ? normalizeIdentifier(rawPhone) : undefined;

  const superAdminRole = roles.get('super_admin');
  if (!superAdminRole) return;

  // One-time backfill: a seed run from before normalization existed may already have created
  // this user under the old, un-normalized phone — reuse that row instead of creating a
  // second "Super Admin" user.
  if (phone && rawPhone && phone !== rawPhone) {
    const legacy = await prisma.user.findUnique({ where: { phone: rawPhone } });
    if (legacy && legacy.phone !== phone) {
      await prisma.user.update({ where: { id: legacy.id }, data: { phone } });
    }
  }

  const user = await prisma.user.upsert({
    where: phone ? { phone } : { email: email! },
    update: {},
    create: { name: 'Super Admin', phone, email },
  });

  await prisma.userRole.upsert({
    where: { userId_roleId: { userId: user.id, roleId: superAdminRole.id } },
    update: {},
    create: { userId: user.id, roleId: superAdminRole.id },
  });

  console.log(`Seeded SuperAdmin user (${phone ?? email}).`);
}

/**
 * The canonical 8-category taxonomy (Category → Subcategory → Type — see
 * `prisma/category-taxonomy.ts`'s own doc comment for the naming/depth rules) — find-or-create
 * by slug at every one of the 152 rows (8 top + 30 sub + 114 type), same discipline as every
 * other seed function in this file: `name`/`description` are admin-editable via `masters.
 * categories` CRUD, so a rerun must never revert an admin's rename. Returns a Map of EVERY
 * node's slug -> id (top-level, Subcategory, and Type alike) so downstream seed data can look up
 * a Deal/Product's `categoryId` (always a top-level slug) and `subcategoryId` (whichever deeper
 * tier — Subcategory or Type — was actually chosen) from the same one Map.
 */
/** Every row here comes from the fixed canonical taxonomy (`category-taxonomy.ts`), so it must
 *  always be reachable in the storefront — `upsert`+force `isActive: true` on every run (not the
 *  old find-or-create-only pattern) so a taxonomy row that got deactivated by some other process
 *  (e.g. a vendor-reset side effect) is unconditionally restored, rather than silently staying
 *  hidden until someone notices and hand-fixes the DB row again. Never touches `name`/`slug`/
 *  `type` on the update path — only the activeness guarantee. */
async function seedCategoryTaxonomy(): Promise<Map<string, string>> {
  const categoryIdBySlug = new Map<string, string>();

  for (const top of CATEGORY_TAXONOMY) {
    const topRow = await prisma.category.upsert({
      where: { slug: top.slug },
      update: { isActive: true },
      create: { name: top.name, slug: top.slug, type: top.type },
    });
    categoryIdBySlug.set(top.slug, topRow.id);

    for (const [subIdx, sub] of top.children.entries()) {
      const subRow = await prisma.category.upsert({
        where: { slug: sub.slug },
        update: { isActive: true },
        create: { name: sub.name, slug: sub.slug, parentId: topRow.id, sortOrder: subIdx },
      });
      categoryIdBySlug.set(sub.slug, subRow.id);

      for (const [leafIdx, leaf] of sub.children.entries()) {
        const leafRow = await prisma.category.upsert({
          where: { slug: leaf.slug },
          update: { isActive: true },
          create: { name: leaf.name, slug: leaf.slug, parentId: subRow.id, sortOrder: leafIdx },
        });
        categoryIdBySlug.set(leaf.slug, leafRow.id);
      }
    }
  }

  return categoryIdBySlug;
}

/** lowercase, non-alphanumeric runs -> single '-', leading/trailing '-' trimmed. */
/**
 * One-off backfill for `Vendor.slug` (added in the Therapist/storefront migration) — every
 * existing Vendor row (the 3 demo vendors, and any other pre-existing row) predates this column,
 * so this walks every Vendor with `slug: null` and assigns one derived from `businessName` (or
 * the row's own `id` if businessName is unset). Idempotent and safe to re-run: only ever touches
 * rows that still have `slug: null`. Shares `ensureUniqueSlug` with `vendor.service.ts`'s
 * `createVendor`/`createSelfVendor`/`updateVendor` — this used to be a local copy of the same
 * fallback logic; now there's one implementation.
 */
async function backfillVendorSlugs(): Promise<number> {
  const vendorsMissingSlug = await prisma.vendor.findMany({ where: { slug: null } });
  for (const v of vendorsMissingSlug) {
    const slug = await ensureUniqueSlug(v.businessName ?? v.id, v.id, (candidate) =>
      prisma.vendor.findUnique({ where: { slug: candidate } }).then(Boolean),
    );
    await prisma.vendor.update({ where: { id: v.id }, data: { slug } });
  }
  return vendorsMissingSlug.length;
}

/** Same demo hours every weekday, a shorter Saturday, closed Sunday — good enough for local dev. */
const DEMO_OPENING_HOURS = {
  mon: '09:00-20:00',
  tue: '09:00-20:00',
  wed: '09:00-20:00',
  thu: '09:00-20:00',
  fri: '09:00-20:00',
  sat: '10:00-18:00',
  sun: 'closed',
};

/** One-off backfill for `Branch.openingHours` (same migration as Vendor.slug) — every existing
 *  Branch row predates this column. Fetches the (small, demo-sized) branch list and filters in
 *  application code rather than a Prisma Json-null `where` clause (Json columns need
 *  `Prisma.DbNull`/`Prisma.JsonNull`, not a bare `null`, and this dataset is small enough that
 *  the extra round-trip cost is irrelevant). Idempotent and safe to re-run. */
async function backfillBranchOpeningHours(): Promise<number> {
  const branches = await prisma.branch.findMany();
  const missing = branches.filter((b) => b.openingHours === null);
  for (const b of missing) {
    await prisma.branch.update({ where: { id: b.id }, data: { openingHours: DEMO_OPENING_HOURS as Prisma.InputJsonValue } });
  }
  return missing.length;
}

// ─── Demo marketplace dataset ────────────────────────────────────────────────
// Category → Sub-category → Product → Deal/Therapist → Vendor → Branch → Cart →
// Checkout → Order → Payment, all as real rows the real APIs already serve — no mock data, no
// parallel demo system, and no separate Booking flow (Deal/Product/Therapist all become
// OrderItems directly). Every function below is safe to re-run: upsert on the model's real
// unique key where one exists (User.phone, Category/Product/Deal.slug, Cart.customerId,
// DealPackage's (dealId,durationMinutes), TherapistPackage's (therapistId,durationMinutes),
// Payment.providerOrderId), or a findFirst-then-create-if-missing guard where it doesn't (Branch,
// Therapist, CartItem, Order). Never `deleteMany` against any of these tables — this only ever
// layers demo rows on top of whatever's already there.

interface ProductSeed {
  name: string;
  slug: string;
  categorySlug: string;
  subcategorySlug: string;
  /** Which seeded vendor (see VENDOR_SEEDS' own `key`) owns this Product — Product is now
   *  vendor-scoped (see the `direct_category_access` migration), never a shared global master. */
  vendorKey: string;
  brand: string;
  description: string;
  price: number;
  originalPrice: number;
}

/** Vendor-owned retail catalog (see Product's schema doc comment). `price` here is just the
 *  catalog reference price; the storefront actually charges each Deal's own `salePrice` (see
 *  `PRODUCT_DEAL_SEEDS` below). Every entry's `categorySlug` is the single new PRODUCT-typed
 *  top-level ("product") — `subcategorySlug` goes all the way to the specific Type-tier row
 *  under it (e.g. "shampoo" under Product > Hair Care), matching the "categoryId is always
 *  top-level, subcategoryId is whichever deeper tier was actually chosen" rule the rest of the
 *  reset taxonomy follows (see `prisma/category-taxonomy.ts`). */
const PRODUCT_SEEDS: ProductSeed[] = [
  { name: 'Hair Shampoo', slug: 'hair-shampoo', categorySlug: 'product', subcategorySlug: 'shampoo', vendorKey: 'glow', brand: 'GlowCare', description: 'Sulphate-free shampoo for everyday use.', price: 499, originalPrice: 599 },
  { name: 'Hair Conditioner', slug: 'hair-conditioner', categorySlug: 'product', subcategorySlug: 'conditioner', vendorKey: 'glow', brand: 'GlowCare', description: 'Deep-conditioning formula for smooth, frizz-free hair.', price: 449, originalPrice: 549 },
  { name: 'Hair Serum', slug: 'hair-serum', categorySlug: 'product', subcategorySlug: 'hair-serum', vendorKey: 'glow', brand: 'GlowCare', description: 'Lightweight serum for shine and split-end control.', price: 699, originalPrice: 799 },
  { name: 'Face Wash', slug: 'face-wash', categorySlug: 'product', subcategorySlug: 'face-wash', vendorKey: 'glow', brand: 'PureSkin', description: 'Gentle daily face wash for all skin types.', price: 299, originalPrice: 349 },
  { name: 'Moisturizer', slug: 'moisturizer', categorySlug: 'product', subcategorySlug: 'moisturizer', vendorKey: 'glow', brand: 'PureSkin', description: 'Hydrating moisturizer for soft, supple skin.', price: 599, originalPrice: 699 },
  { name: 'Body Scrub', slug: 'body-scrub', categorySlug: 'product', subcategorySlug: 'body-scrub-product', vendorKey: 'urban', brand: 'UrbanSpa', description: 'Exfoliating body scrub for smoother skin.', price: 399, originalPrice: 499 },
  { name: 'Massage Oil', slug: 'massage-oil', categorySlug: 'product', subcategorySlug: 'massage-oil', vendorKey: 'urban', brand: 'UrbanSpa', description: 'Aromatic massage oil for relaxation.', price: 349, originalPrice: 429 },
  { name: 'Spa Kit', slug: 'spa-kit', categorySlug: 'product', subcategorySlug: 'spa-kit', vendorKey: 'serenity', brand: 'SerenityHome', description: 'At-home spa essentials kit for a relaxing retreat.', price: 799, originalPrice: 999 },
  { name: 'Essential Oil Blend', slug: 'essential-oil-blend', categorySlug: 'product', subcategorySlug: 'essential-oils', vendorKey: 'serenity', brand: 'SerenityHome', description: 'Calming essential oil blend for aromatherapy.', price: 599, originalPrice: 749 },
  { name: 'Daily Sunscreen', slug: 'daily-sunscreen', categorySlug: 'product', subcategorySlug: 'sunscreen', vendorKey: 'vitality', brand: 'VitalityCare', description: 'Broad-spectrum daily sunscreen, SPF 50.', price: 399, originalPrice: 499 },
  { name: 'Personal Care Kit', slug: 'personal-care-kit', categorySlug: 'product', subcategorySlug: 'personal-care', vendorKey: 'vitality', brand: 'VitalityCare', description: 'Everyday personal care essentials kit.', price: 899, originalPrice: 1099 },
];

async function seedProducts(categoryIdBySlug: Map<string, string>, vendorIdByKey: Map<string, string>): Promise<Map<string, string>> {
  const productIdBySlug = new Map<string, string>();
  for (const prod of PRODUCT_SEEDS) {
    const discount = Math.round(((prod.originalPrice - prod.price) / prod.originalPrice) * 100);
    const data = {
      vendorId: vendorIdByKey.get(prod.vendorKey)!,
      name: prod.name,
      brand: prod.brand,
      categoryId: categoryIdBySlug.get(prod.categorySlug)!,
      subcategoryId: categoryIdBySlug.get(prod.subcategorySlug)!,
      description: prod.description,
      summary: prod.description,
      // Was keyed off `categorySlug` (which distinguished "beauty-products" vs "wellness-products"
      // pre-reset) — every PRODUCT_SEEDS entry now shares the single new "product" top-level, so
      // this keys off `subcategorySlug` (the Type-tier row) instead, which still carries the
      // same relaxation-vs-skin/hair distinction.
      benefits: [`Improves ${['massage-oil', 'body-scrub-product'].includes(prod.subcategorySlug) ? 'relaxation' : 'skin/hair health'}`] as Prisma.InputJsonValue,
      howToUse: ['Apply as directed', 'Use regularly for best results'] as Prisma.InputJsonValue,
      ingredients: 'See packaging for full ingredient list.',
      returnPolicy: '7-day return if unopened.',
      image: `https://picsum.photos/seed/product-${prod.slug}/600/400`,
      gallery: [`https://picsum.photos/seed/product-${prod.slug}-2/600/400`] as Prisma.InputJsonValue,
      imageAlt: prod.name,
      price: prod.price,
      originalPrice: prod.originalPrice,
      discount,
      isActive: true,
    };
    // Find-or-create: Product name/description/price/etc. are admin-editable — never overwrite.
    const row = (await prisma.product.findUnique({ where: { slug: prod.slug } }))
      ?? (await prisma.product.create({ data: { ...data, slug: prod.slug } }));
    productIdBySlug.set(prod.slug, row.id);
  }
  return productIdBySlug;
}

